from content_helpers import code, output, choice, lesson, section, program

def sections():
    return [section("algorithms", "9. Стандартные алгоритмы", "Итераторы, поиск, сортировка и оценка затрат.", [
        lesson("iterators", "Диапазон begin / end", "Передайте алгоритму нужную часть коллекции.",
            "Итератор обозначает позицию в последовательности. values.begin() указывает на начало, values.end() — позицию за последним элементом. Алгоритмы обычно принимают полуинтервал [begin,end): начало включено, конец исключён. Пустой диапазон имеет begin==end. end нельзя разыменовывать.\n\nИз <algorithm> доступен std::count(values.begin(), values.end(), target), считающий совпадения. std::find возвращает итератор первого совпадения или переданный end, если совпадений нет. Итератор можно сравнить с end и только после проверки прочитать элемент через *it. Здесь auto сохраняет точный тип итератора. Перемещение итераторов вручную пока не требуется.",
            program('std::vector<int> v = {2, 7, 2};\nstd::cout << std::count(v.begin(), v.end(), 2);', "iostream vector algorithm"),
            "end — не последний элемент и не место для нового элемента. Полуинтервал позволяет одинаково представить пустой и непустой набор. Сначала проверьте результат find, затем используйте *it.",
            "Алгоритмы получают диапазон [begin,end). Для результата поиска проверка отсутствия обязательна.", [
                code("count", "Частота метки", 'Ввод: n (0…100), n целых меток (0…99), затем target. Используйте std::count и выведите число совпадений.', 'int n = 0;\nstd::cin >> n;\nstd::vector<int> v(n);\nfor (int i = 0; i < n; ++i) { std::cin >> v[i]; }\nint target = 0;\nstd::cin >> target;\nstd::cout << std::count(v.begin(), v.end(), target);', [("4 2 7 2 2 2", "3"), ("0 9", "0")], ["Передайте полный диапазон вектора.", "Третий аргумент count — искомое значение."], "Пустой диапазон корректен: число совпадений равно нулю.", headers="iostream vector algorithm"),
                code("find", "Метка существует?", 'Ввод: n (0…100), n меток (0…99), затем target. Через std::find выведите Found или Missing.', 'int n = 0;\nstd::cin >> n;\nstd::vector<int> v(n);\nfor (int i = 0; i < n; ++i) { std::cin >> v[i]; }\nint target = 0;\nstd::cin >> target;\nauto it = std::find(v.begin(), v.end(), target);\nif (it != v.end()) { std::cout << "Found"; }\nelse { std::cout << "Missing"; }', [("3 4 2 8 2", "Found"), ("0 2", "Missing")], ["Сравните результат с тем же end, который передали алгоритму.", "Не превращайте итератор в bool."], "Не найдено обозначается концом диапазона, а не нулевым индексом.", headers="iostream vector algorithm"),
                output("end", "Пустой диапазон", 'std::vector<int> v;\nstd::cout << (v.begin() == v.end());', "1", ["У пустой коллекции нет первого элемента.", "Начало и конец диапазона совпадают."], "Равенство итераторов не означает допустимость чтения через них.", headers="iostream vector"),
                code("reverse", "Разворот алгоритмом", 'Ввод: n (0…100), затем n чисел (−100…100). Примените std::reverse к vector и выведите результат через пробел.', 'int n = 0;\nstd::cin >> n;\nstd::vector<int> v(n);\nfor (int i = 0; i < n; ++i) { std::cin >> v[i]; }\nstd::reverse(v.begin(), v.end());\nfor (int i = 0; i < n; ++i) {\n    if (i > 0) { std::cout << " "; }\n    std::cout << v[i];\n}', [("4 1 3 8 2", "2 8 3 1"), ("0", "")], ["reverse меняет значения в переданном диапазоне.", "После вызова выводите в обычном порядке."], "Алгоритм меняет содержимое, но не размер контейнера.", headers="iostream vector algorithm")
            ], ["итераторы", "диапазоны", "algorithm"]),
        lesson("sorting", "Сортировка", "Упорядочьте значения и используйте порядок.",
            "std::sort из <algorithm> сортирует элементы вектора по возрастанию: std::sort(v.begin(), v.end());. Равные элементы сохраняются, их взаимный порядок sort не обещает сохранять. Для числовых значений без дополнительных полей это различие обычно незаметно. Пустой и одиночный диапазоны корректны.\n\nПосле сортировки минимум расположен в начале, максимум в конце, но чтение v[0] и v[n-1] допустимо только при n>0. Сортировка изменяет исходный порядок — если он нужен позже, сначала сделайте копию. Для сортировки по убыванию можно отсортировать по возрастанию, затем применить reverse; иной вариант — компаратор, который изучим после базовой модели.",
            program('std::vector<int> v = {4, 1, 4, 2};\nstd::sort(v.begin(), v.end());\nfor (int x : v) { std::cout << x; }', "iostream vector algorithm"),
            "Стандарт задаёт требования и сложность sort, а не один конкретный внутренний алгоритм реализации. Не называйте его обязательно быстрой сортировкой. При работе с одинаковыми ключами отдельные данные могут требовать stable_sort, но это дополнительный контракт.",
            "Сортировка меняет порядок, не удаляет повторы. Перед чтением крайних элементов проверьте непустоту.", [
                code("sort", "Очередь по массе", 'Ввод: n (0…100), затем n масс (0…100). Отсортируйте их по возрастанию и выведите через пробел, сохранив повторы.', 'int n = 0;\nstd::cin >> n;\nstd::vector<int> v(n);\nfor (int i = 0; i < n; ++i) { std::cin >> v[i]; }\nstd::sort(v.begin(), v.end());\nfor (int i = 0; i < n; ++i) {\n    if (i > 0) { std::cout << " "; }\n    std::cout << v[i];\n}', [("5 4 1 4 2 0", "0 1 2 4 4"), ("0", "")], ["Нужен полный диапазон v.", "Выводите n значений после sort, не удаляя равные."], "Равные массы — отдельные элементы очереди.", headers="iostream vector algorithm"),
                code("median", "Срединный датчик", 'Ввод: нечётное n (1…99), затем n целых значений (−100…100). Выведите медиану: элемент с индексом n/2 после сортировки.', 'int n = 0;\nstd::cin >> n;\nstd::vector<int> v(n);\nfor (int i = 0; i < n; ++i) { std::cin >> v[i]; }\nstd::sort(v.begin(), v.end());\nstd::cout << v[n / 2];', [("5 9 1 7 2 4", "4"), ("1 -8", "-8")], ["Медиана не равна среднему арифметическому в общем случае.", "Упорядочьте значения и возьмите центральный индекс."], "Нечётность и непустота явно гарантированы условием.", headers="iostream vector algorithm", difficulty=2),
                choice("duplicates", "Исчезнут ли повторы?", 'Что станет с двумя равными значениями после std::sort?', ["Оба останутся в последовательности", "Всегда останется только одно", "Оба будут удалены"], 0, ["sort меняет порядок, не размер.", "Удаление повторов — отдельная операция."], "Нельзя подменять сортировку уникализацией."),
                code("copy", "Исходник и рейтинг", 'Ввод: n (1…100), затем n чисел (−100…100). Скопируйте vector, отсортируйте только копию. Выведите первый элемент исходника и наименьшее значение через пробел.', 'int n = 0;\nstd::cin >> n;\nstd::vector<int> original(n);\nfor (int i = 0; i < n; ++i) { std::cin >> original[i]; }\nstd::vector<int> sorted = original;\nstd::sort(sorted.begin(), sorted.end());\nstd::cout << original[0] << " " << sorted[0];', [("3 8 1 4", "8 1"), ("1 7", "7 7")], ["Копия vector имеет независимые значения.", "Вызов sort должен получать итераторы sorted, не original."], "Хранение исходного порядка — явное архитектурное решение, а не свойство sort.", headers="iostream vector algorithm", difficulty=2)
            ], ["sort", "медиана", "копирование"]),
        lesson("complexity", "Сложность и двоичный поиск", "Сравните число шагов при росте входа.",
            "O(n) описывает верхнюю асимптотическую оценку роста затрат, а не точное время в секундах. Один проход обычно делает число проверок, пропорциональное n. Два последовательных прохода — всё ещё O(n); два вложенных полных прохода — O(n²). std::sort требует O(n log n) сравнений в принятой модели.\n\nstd::binary_search(v.begin(),v.end(),target) ищет наличие значения в отсортированном диапазоне и возвращает bool. Для vector число сравнений логарифмическое. Если сортировать ради единственного поиска, общая подготовка обычно дороже линейного поиска. Для многих поисков порядок может окупиться. Предпосылки алгоритма обязательны: не используйте binary_search на произвольном неупорядоченном входе.",
            program('std::vector<int> v = {1, 3, 3, 9};\nstd::cout << std::binary_search(v.begin(), v.end(), 3);', "iostream vector algorithm"),
            "Сложность зависит от модели и структуры данных. Логарифмическое число сравнений не означает логарифмическое число всех операций для любых итераторов. Здесь контейнер vector поддерживает произвольный доступ, поэтому упрощённая модель уместна.",
            "Учитывайте подготовку данных и число запросов. Предусловия важнее названия «быстрый поиск».", [
                code("binary", "Запрос к каталогу", 'Ввод: n (0…100), n произвольных чисел (0…99), затем target. Отсортируйте vector, примените binary_search и выведите 1 или 0.', 'int n = 0;\nstd::cin >> n;\nstd::vector<int> v(n);\nfor (int i = 0; i < n; ++i) { std::cin >> v[i]; }\nint target = 0;\nstd::cin >> target;\nstd::sort(v.begin(), v.end());\nstd::cout << std::binary_search(v.begin(), v.end(), target);', [("4 9 1 3 3 3", "1"), ("0 2", "0"), ("2 1 9 5", "0")], ["Вход не обещан отсортированным.", "Сначала sort, затем binary_search с target."], "Проверяем наличие, а не индекс или число совпадений.", headers="iostream vector algorithm"),
                code("requests", "Несколько запросов", 'Ввод: n (0…100), n чисел (0…99), q (0…100), затем q искомых значений. Отсортируйте один раз и выведите для каждого запроса 1/0 на отдельной строке с завершающим переносом.', 'int n = 0;\nstd::cin >> n;\nstd::vector<int> v(n);\nfor (int i = 0; i < n; ++i) { std::cin >> v[i]; }\nstd::sort(v.begin(), v.end());\nint q = 0;\nstd::cin >> q;\nfor (int i = 0; i < q; ++i) {\n    int target = 0;\n    std::cin >> target;\n    std::cout << std::binary_search(v.begin(), v.end(), target) << "\\n";\n}', [("3 7 2 4 3 2 3 7", "1\n0\n1\n"), ("0 0", "")], ["Подготовку не нужно повторять на каждом запросе.", "Вынесите sort до цикла чтения q запросов."], "Разделение подготовки и запросов меняет общую оценку затрат.", headers="iostream vector algorithm", difficulty=2),
                choice("passes", "Два прохода", 'Какова оценка числа действий двух последовательных полных проходов по n элементам?', ["O(n)", "O(n²)", "O(1)"], 0, ["Число действий складывается, а не перемножается.", "Константный множитель 2 не меняет порядок роста."], "Вложенность и последовательность — разные структуры алгоритма."),
                code("distinct", "Сколько разных меток?", 'Ввод: n (0…100), n чисел (0…99). Отсортируйте и посчитайте число различных значений сравнением соседей.', 'int n = 0;\nstd::cin >> n;\nstd::vector<int> v(n);\nfor (int i = 0; i < n; ++i) { std::cin >> v[i]; }\nstd::sort(v.begin(), v.end());\nint count = 0;\nfor (int i = 0; i < n; ++i) {\n    if (i == 0 || v[i] != v[i - 1]) { ++count; }\n}\nstd::cout << count;', [("5 3 1 3 2 1", "3"), ("0", "0"), ("3 7 7 7", "1")], ["После сортировки одинаковые значения стоят рядом.", "Первый элемент начинает первую группу, остальные — при отличии от предыдущего."], "Проверка i==0 слева от || защищает обращение к i-1 коротким замыканием.", headers="iostream vector algorithm", difficulty=2)
            ], ["сложность", "binary_search", "предусловия"]),
        lesson("tournament", "Мини-проект: турнир", "Объедините сортировку, проверку и выбор результата.",
            "В турнирных задачах важны правила ничьих. Второе место может означать второй элемент рейтинга или второе различное значение. В этом уроке такие различия указаны явно. Не выводите результат из названия задачи — читайте контракт.\n\nЧтобы получить k лучших результатов, отсортируйте по возрастанию и пройдите от n-1 вниз. Для второго различного максимума можно после сортировки искать первое значение меньше последнего. Случай «все одинаковы» должен иметь отдельный результат. Проверка на неубывание сравнивает соседей и не требует изменения входа.",
            program('std::vector<int> scores = {8, 10, 10, 7};\nstd::sort(scores.begin(), scores.end());\nstd::cout << scores[3] << " " << scores[2];', "iostream vector algorithm"),
            "Проверка требований включает повторяющиеся значения. Тест без ничьих не отличит два разных смысла «второго места». Это пример того, как неоднозначная постановка создаёт несколько правильных алгоритмов для разных задач.",
            "Явно определите ничьи, отсутствие результата и порядок вывода.", [
                code("top", "Лучшие k результатов", 'Ввод: n (1…100), k (1…n), затем n баллов (0…100). Выведите k наибольших по убыванию через пробел. Равные баллы занимают отдельные позиции.', 'int n = 0, k = 0;\nstd::cin >> n >> k;\nstd::vector<int> v(n);\nfor (int i = 0; i < n; ++i) { std::cin >> v[i]; }\nstd::sort(v.begin(), v.end());\nfor (int i = 0; i < k; ++i) {\n    if (i > 0) { std::cout << " "; }\n    std::cout << v[n - 1 - i];\n}', [("4 3 8 10 10 7", "10 10 8"), ("1 1 0", "0")], ["Повторы не удаляются.", "После сортировки берите индексы n-1, n-2, ..."], "Второй результат может совпадать с первым; это соответствует отдельным позициям.", headers="iostream vector algorithm", difficulty=2),
                code("second", "Второй различный максимум", 'Ввод: n (1…100), n баллов (0…100). Выведите наибольший балл, строго меньший максимума, или None, если такого нет.', 'int n = 0;\nstd::cin >> n;\nstd::vector<int> v(n);\nfor (int i = 0; i < n; ++i) { std::cin >> v[i]; }\nstd::sort(v.begin(), v.end());\nint found = -1;\nfor (int i = n - 2; i >= 0; --i) {\n    if (v[i] < v[n - 1]) { found = v[i]; break; }\n}\nif (found == -1) { std::cout << "None"; }\nelse { std::cout << found; }', [("4 8 10 10 7", "8"), ("3 5 5 5", "None"), ("1 0", "None")], ["Пропустите все значения, равные максимуму.", "Маркер −1 безопасен здесь, потому что баллы неотрицательны."], "Маркер выбирается по контракту диапазона значений, а не механически для всех задач.", headers="iostream vector algorithm", difficulty=3),
                choice("tie", "Два смысла второго места", 'Для баллов 10,10,8 какой второй различный максимум?', ["10", "8", "Не существует"], 1, ["Различный означает строго меньше максимума.", "Повтор 10 не создаёт новое различное значение."], "Второй элемент рейтинга и второй различный максимум — разные требования."),
                code("ordered", "Рейтинг уже готов?", 'Ввод: n (0…100), n баллов (0…100). Без сортировки выведите Yes, если они уже идут неубывающе, иначе No. Пустой и одиночный набор подходят.', 'int n = 0;\nstd::cin >> n;\nstd::vector<int> v(n);\nfor (int i = 0; i < n; ++i) { std::cin >> v[i]; }\nbool ordered = true;\nfor (int i = 1; i < n; ++i) {\n    if (v[i] < v[i - 1]) { ordered = false; }\n}\nstd::cout << (ordered ? "Yes" : "No");', [("4 1 2 2 9", "Yes"), ("3 1 9 2", "No"), ("0", "Yes")], ["Равные соседи допустимы.", "Ищите пару, в которой следующий элемент меньше предыдущего."], "Условный оператор condition ? a : b выбирает одно из двух выражений; здесь он лишь сокращает вывод if/else.", headers="iostream vector", difficulty=2)
            ], ["мини-проект", "сортировка", "ничьи"])
    ])]
